changeSet.sql:
UPDATE cmr_feedback SET entry_type = CASE
    WHEN type = 'zero_result' THEN 'zero'
    ELSE 'mismatch' END
WHERE entry_type IS NULL;
UPDATE cmr_feedback SET status = 'pending' WHERE status = 'processing';
UPDATE cmr_feedback SET status = 'handled' WHERE status = 'closed';
UPDATE cmr_feedback SET disposition = CASE
    WHEN target = 'datasource' THEN 'block'
    WHEN target = 'strategy' THEN 'strategy'
    WHEN target = 'backfill' THEN 'supplement'
    ELSE disposition END
WHERE disposition IS NULL;
UPDATE cmr_feedback SET blocked = 1
WHERE disposition = 'block' AND status = 'handled';
